<?php $title="Service Center";require "includes/header.php";$r=$conn->query("SELECT s.*,c.name customer,b.name bicycle FROM service s JOIN customers c ON c.id=s.customer_id JOIN bicycles b ON b.id=s.bicycle_id ORDER BY s.service_date DESC");?><div class="section-title"><div><h2>🔧 Service Center</h2><p class="muted">Repair and maintenance tracking.</p></div><a class="btn primary" href="add_service.php">+ New Service</a></div><div class="card"><table><tr><th>Customer</th><th>Bicycle</th><th>Service</th><th>Status</th><th>Date</th><th>Cost</th></tr><?php while($x=$r->fetch_assoc()):?><tr><td><?=e($x["customer"])?></td><td><?=e($x["bicycle"])?></td><td><?=e($x["service_type"])?></td><td><span class="badge"><?=e($x["status"])?></span></td><td><?=e($x["service_date"])?></td><td><?=money($x["cost"])?></td></tr><?php endwhile;?></table></div><?php require "includes/footer.php";?>